@@ -43,4 +43,55 @@
 </aside>
 </div></div>
 <div class="toast" id="toast"></div><div class="modal-back" id="modalBack"><div class="modal" id="modal"></div></div>
 <script>
+const holdings=[
+{id:'greywatch',name:'Greywatch Keep',realm:'The Vale Marches',type:'Small castle',garrison:50,owner:'independent',x:218,y:210,days:2,loot:38},
+{id:'thornmere',name:'Thornmere',realm:'The Vale Marches',type:'Market town',garrison:32,owner:'independent',x:168,y:275,days:3,loot:24},
+{id:'sunspire',name:'Sunspire',realm:'The Amber Coast',type:'Small castle',garrison:58,owner:'independent',x:278,y:158,days:4,loot:46},
+{id:'westmere',name:'Westmere',realm:'Kingdom of Alder',type:'Border castle',garrison:96,owner:'hostile',x:145,y:155,days:5,loot:60},
+{id:'ironhold',name:'Ironhold',realm:'Kingdom of Alder',type:'Grand fortress',garrison:480,owner:'hostile',x:237,y:111,days:9,loot:140},
+{id:'redfen',name:'Redfen Crossing',realm:'The Vale Marches',type:'River settlement',garrison:40,owner:'independent',x:267,y:278,days:4,loot:32},
+{id:'ravenpass',name:'Raven Pass',realm:'The Vale Marches',type:'Mountain keep',garrison:74,owner:'independent',x:178,y:120,days:5,loot:54},
+{id:'goldenreach',name:'Golden Reach',realm:'Empire of Saffron',type:'Walled city',garrison:360,owner:'hostile',x:504,y:177,days:12,loot:150},
+{id:'ashcourt',name:'Ashcourt',realm:'Empire of Saffron',type:'Great castle',garrison:510,owner:'hostile',x:547,y:120,days:15,loot:180},
+{id:'ivorygate',name:'Ivory Gate',realm:'Kingdom of Kemet',type:'Desert citadel',garrison:105,owner:'hostile',x:707,y:270,days:17,loot:84},
+{id:'jadeharbor',name:'Jade Harbor',realm:'Kingdom of Lian',type:'Coastal keep',garrison:83,owner:'independent',x:770,y:225,days:20,loot:65},
+{id:'moonwell',name:'Moonwell',realm:'Kingdom of Lian',type:'Hill fortress',garrison:540,owner:'hostile',x:738,y:300,days:21,loot:190}
+];
+let state={name:'Aren Vale',gender:'male',year:1087,season:0,gold:120,food:85,soldiers:24,renown:3,xp:40,level:1,turn:0,selected:holdings[0],quests:0,zoom:1,events:[],language:'English'};
+const seasons=['SPRING','SUMMER','AUTUMN','WINTER'];
+const $=id=>document.getElementById(id);
+function render(){
+ $('date').textContent=`${seasons[state.season]} · ${state.year}`;
+ $('heroName').textContent=state.name;$('heroRank').textContent=(state.level<3?'Footsoldier':state.level<6?'Sergeant':'Banner Captain')+' · House '+(state.name.split(' ').pop()||'Vale');
+ $('level').textContent=state.level;$('xpText').textContent=`${state.xp} / ${state.level*100} XP`;$('xpBar').style.width=Math.min(100,state.xp/(state.level*100)*100)+'%';
+ $('gold').innerHTML=state.gold+'<span>+'+(8+state.territories||8)+'</span>';$('food').innerHTML=state.food+'<span>+5</span>';$('soldiers').innerHTML=state.soldiers+'<span>◈</span>';$('renown').innerHTML=state.renown+'<span>pts</span>';
+ const h=state.selected;$('targetName').textContent=h.name;$('targetBadge').textContent=h.owner==='player'?'Your holding':h.owner==='hostile'?'Great kingdom':'Independent';$('targetMeta').textContent=h.realm+' · '+h.type;$('targetGarrison').textContent=h.owner==='player'?'Garrison secure':`${h.garrison} guards`;$('targetDistance').textContent=h.owner==='player'?'Home territory':`${h.days} days`;
+ const ratio=h.garrison/Math.max(1,state.soldiers);$('threatText').textContent=h.owner==='player'?'Secure':ratio<1?'Favorable':ratio<2?'Even odds':ratio<5?'Difficult':'Overwhelming';$('threatBar').style.width=Math.min(100,ratio*18)+'%';$('threatBar').style.background=ratio<1?'#77966d':ratio<3?'#bd9a50':'#ad5d4f';
+ $('attackBtn').textContent=h.owner==='player'?'Rename':h.owner==='hostile'?'⚔  Challenge':'⚔  Challenge';$('attackBtn').disabled=h.owner==='hostile'&&state.soldiers<Math.min(45,h.garrison*.35);
+ $('targetCount').textContent=String(holdings.indexOf(h)+1).padStart(2,'0')+' / '+String(holdings.length).padStart(2,'0');
+ $('questCount').textContent=Math.min(state.quests,4)+' / 1';$('questBar').style.width=(state.quests?100:30)+'%';
+ $('portrait').textContent=state.gender==='male'?'🧑🏻‍🌾':'👩🏽‍🌾';
+ drawMap();drawEvents();
+}
+function drawMap(){const group=$('locations');group.innerHTML='';holdings.forEach(h=>{let g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','location'+(state.selected.id===h.id?' selected':''));g.setAttribute('transform',`translate(${h.x},${h.y})`);g.innerHTML=`<circle r="${state.selected.id===h.id?8:6}" fill="${h.owner==='player'?'#557d59':h.owner==='hostile'?'#a75043':'#b68d43'}"></circle><text x="10" y="3">${h.name}</text>`;g.addEventListener('click',e=>{e.stopPropagation();state.selected=h;render()});group.appendChild(g)});
+}
+function drawEvents(){const list=$('eventList');list.innerHTML='';const items=state.events.slice(-3).reverse();if(!items.length){items.push({icon:'♜',text:'Kingdoms of the Known World gather beneath their banners.',time:`${seasons[state.season]} · ${state.year}`},{icon:'✉',text:'A royal courier arrives with word from the capital.',time:'3 DAYS AGO'})}items.forEach(e=>{let el=document.createElement('div');el.className='event';el.innerHTML=`<div class="event-icon">${e.icon}</div><div><p>${e.text}</p><time>${e.time}</time></div>`;list.appendChild(el)})}
+function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
+function log(text,icon='✦'){state.events.push({icon,text,time:`${seasons[state.season]} · ${state.year}`});drawEvents()}
+function gainXP(n){state.xp+=n;if(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.renown+=2;state.soldiers+=5;log(`${state.name} rose to level ${state.level}. Five volunteers joined your banner.`,'⬆');toast(`LEVEL UP · You are now level ${state.level}!`)}}
+function advanceTurn(){state.turn++;state.season=(state.season+1)%4;if(state.season===0)state.year++;state.gold+=8;state.food+=5;if(state.soldiers>0)state.food-=Math.ceil(state.soldiers/40);if(state.food<0){state.food=0;state.soldiers=Math.max(1,state.soldiers-3);log('A lean winter thinned the ranks. Provisions are running low.','!')}
+ if(state.turn%3===0){const rivals=holdings.filter(h=>h.owner!=='player'&&h.owner!=='independent');if(rivals.length&&Math.random()<.48){let h=rivals[Math.floor(Math.random()*rivals.length)];log(`${h.realm} has been seen mustering troops near ${h.name}.`,'⚑');}}
+ render();}
+function openModal(title,subtitle,body,actions){$('modal').innerHTML=`<div class="eyebrow">${subtitle||'FATEBEARER · CHRONICLE OF CROWNS'}</div><h2>${title}</h2><div class="modal-body">${body}</div><div class="modal-actions">${actions||'<button class="btn" data-close>Continue</button>'}</div>`;$('modalBack').classList.add('open');$('modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
+function closeModal(){$('modalBack').classList.remove('open')}
+function attack(){const h=state.selected;if(h.owner==='player'){renameHolding();return}if(state.soldiers<Math.max(12,Math.floor(h.garrison*.22))){toast('Gather more soldiers before marching.');return}
+ const odds=Math.max(.08,Math.min(.93,(state.soldiers*1.35+state.level*9+state.renown*2)/(h.garrison+state.soldiers*1.35)));
+ const battle=`<div class="battlefield"><div class="battle-caption">${h.name} · ${h.garrison} defenders</div><div class="troop-row">🛡️ ⚔️ 🏹 🛡️</div><div class="troop-row enemy">⚔️ 🏹 🛡️ ⚔️</div></div><b>Estimated chance of victory: ${Math.round(odds*100)}%</b><br><span style="font-size:11px;color:#879084">Your ${state.soldiers} troops · ${h.garrison} defenders · ${h.days} day march</span><p style="font-size:11px">Victory may cost soldiers. Your scouts can make the difference between glory and grief.</p>`;
+ openModal('March on '+h.name,'BATTLE PREPARATION',battle,`<button class="btn secondary" data-close>Not yet</button><button class="btn gold" id="marchNow">⚔ &nbsp;Lead the charge</button>`);$('marchNow').onclick=()=>{closeModal();advanceTurn();const win=Math.random()<odds;let losses=Math.max(2,Math.floor(state.soldiers*(win?.18:.45+Math.random()*.22)));state.soldiers=Math.max(0,state.soldiers-losses);if(win){h.owner='player';h.garrison=Math.max(12,Math.floor(state.soldiers*.3));state.gold+=h.loot;state.food+=18;state.renown+=4;gainXP(45);log(`${state.name} captured ${h.name} from ${h.realm}, claiming ${h.loot} gold.`,'⚔');toast(`VICTORY · ${h.name} joins your lands!`);if(state.quests===0){state.quests=1;$('questTitle').textContent='Gather your banner';$('questText').textContent='Raise a levy, then scout the frontier. Your first keep is only the beginning.'}}else{gainXP(15);log(`The assault on ${h.name} was repelled. ${losses} soldiers did not return.`,'⚔');toast(`DEFEAT · Regroup and rebuild your strength.`)}render()};
+}
+function renameHolding(){const h=state.selected;openModal('A name for the ages','YOUR DOMAIN',`<p>Rename <b>${h.name}</b> and mark it with your family legacy.</p><div class="form-row"><input id="renameInput" maxlength="24" value="${h.name}" aria-label="Holding name"></div>`,`<button class="btn secondary" data-close>Cancel</button><button class="btn" id="saveName">Save name</button>`);$('saveName').onclick=()=>{h.name=$('renameInput').value.trim()||h.name;log(`${h.name} was entered into the family rolls.`,'♜');closeModal();render();toast('Your banner has a new home.')};}
+$('attackBtn').onclick=attack;
+$('scoutBtn').onclick=()=>{advanceTurn();state.gold=Math.max(0,state.gold-5);let h=holdings.filter(x=>x.owner==='independent'&&x!==state.selected).sort((a,b)=>a.garrison-b.garrison)[0];if(h){state.selected=h;state.renown++;gainXP(18);log(`Scouts discovered ${h.name}: ${h.garrison} defenders and a modest treasury.`,'⌕');toast(`Scouts report: ${h.name} looks vulnerable.`)}else{gainXP(12);toast('The frontier is mapped. Your scouts return safely.')}if(state.quests===0)state.quests=1;render()};
+$('recruitBtn').onclick=()=>{if(state.gold<30){toast('The treasury needs 30 gold.');return}state.gold-=30;state.soldiers+=20;gainXP(8);log(`Twenty new recruits swore the oath to House ${state.name.split(' ').pop()}.`,'⚔');toast('Twenty soldiers join your banner.');if(state.quests===1){state.quests=2;$('questTitle').textContent='A voice in the council';$('questText').textContent='Seek an audience with the queen. Your first victories earn a hearing.'}render()};
+$('talkBtn').onclick=()=>{const h=state.selected;if(h.owner==='player'){renameHolding();return}openModal('A parley beneath banners','DIPLOMACY · '+h.name,`A herald from <b>${h.name}</b> awaits your words. A generous offer may avert bloodshed, but they will not hand over their keys without reason.<div class="stats"><div class="stat"><label>Their mood</label><b>${h.owner==='hostile'?'Wary':'Cautious'}</b></div><div class="stat"><label>Your renown</label><b>${state.renown} points</b></div></div>`, `<button class="btn secondary" data-close>Depart</button><button class="btn" id="offerGold">Offer 25 gold</button><button class="btn gold" id="requestOath">Request oath</button>`);$('offerGold').onclick=()=>{if(state.gold<25){toast('You do not have enough gold.');return}state.gold-=25;if(h.owner==='independent'&&Math.random()<.68){h.owner='player';h.garrison=20;state.renown+=2;gainXP(25);log(`${h.name} swore fealty after a generous parley.`,'✉');toast('A bloodless victory!')}else{log(`The parley at ${h.name} ended without an agreement.`,'✉');toast('They refused your offer.')}closeModal();render()};$('requestOath').onclick=()=>{if(h.owner==='independent'&&state.renown>=5){h.owner='player';h.garrison=18;state.renown-=2;gainXP(25);log(`${h.name} joined your banner, impressed by your renown.`,'♜');toast('The holding swears fealty!')}else{toast('Build renown (5+) to make this request credible.')}closeModal();render()}};

