function saveGame(){try{const snapshot={...state,selectedId:state.selected.id,events:state.events};delete snapshot.selected;snapshot.selectedId=state.selected.id;localStorage.setItem('fatebearer-save',JSON.stringify(snapshot))}catch(e){}}
function loadGame(){try{const saved=JSON.parse(localStorage.getItem('fatebearer-save')||'null');if(saved){const id=saved.selectedId;delete saved.selectedId;state={...state,...saved};state.selected=holdings.find(h=>h.id===id)||holdings[0];return true}}catch(e){}return false}
// Restore campaign progress before showing the opening scene.
const hadSave=loadGame();render();setTimeout(()=>{if(!hadSave&&!localStorage.getItem('fatebearer-intro')){openModal('The marches await','A NEW CHRONICLE · SPRING 1087',`You are an ordinary recruit in a small border kingdom. Beyond these green valleys lie three continents, a hundred great crowns, and a thousand untold stories.<br><br>Choose your name and bearing. Captain Elowen has marked a modest keep nearby. Scout, gather your companions, and earn your first place in history.<div class="form-row"><input id="startName" maxlength="24" value="Aren Vale" aria-label="First and family name"><select id="startGender" aria-label="Character appearance"><option value="male">Male · Wanderer</option><option value="female">Female · Wanderer</option></select></div>`,`<button class="btn" id="begin">Take up your banner</button>`);$('begin').onclick=()=>{state.name=$('startName').value.trim()||'Aren Vale';state.gender=$('startGender').value;localStorage.setItem('fatebearer-intro','seen');closeModal();render();saveGame()}}},350);
setInterval(saveGame,12000);

